 ) AS v(ten,slug,category,brand,cpu,gpu,ram,storage,screen,os,price,image,source) LOOP
  SELECT "MaPhanLoai" INTO category_id FROM "PhanLoai" WHERE "DuongDan"=r.category;
  SELECT "MaThuongHieu" INTO brand_id FROM "ThuongHieu" WHERE "DuongDan"=r.brand;
  IF category_id IS NULL OR brand_id IS NULL THEN RAISE EXCEPTION 'Missing category or brand for %',r.slug; END IF;
  product_id := NULL;
  VALUES (category_id,brand_id,r.ten,r.slug,lower(r.ten),'Sản phẩm tham khảo từ CellphoneS.','Giá và ảnh tham khảo từ CellphoneS; tồn kho là dữ liệu thử nghiệm.',0,'{}'::jsonb,r.source,DATE '2026-11-16',true,true,now()) ON CONFLICT ("DuongDan") DO NOTHING RETURNING "MaSanPham" INTO product_id;
  IF product_id IS NULL THEN CONTINUE; END IF;
  VALUES (product_id,'CPS-'||upper(r.slug),'Phiên bản tham khảo','Theo ảnh',r.cpu,r.gpu,r.ram,r.storage,r.screen,r.os,'{}'::jsonb,r.price,r.price,0,true,now()) RETURNING "MaBienThe" INTO sku_id;
 END LOOP;
END $seed$;

CREATE TEMP TABLE "CpsThongSoMoi" (slug text, category text, code text, label text, value text) ON COMMIT DROP;
SELECT DISTINCT p."MaPhanLoai",c.code,c.label,'CHU',500 FROM "CpsThongSoMoi" c JOIN "PhanLoai" p ON p."DuongDan"=c.category ON CONFLICT ("MaPhanLoai","KyHieu") DO NOTHING;
SELECT b."MaBienThe",s."MaSanPham",s."MaPhanLoai",t."MaThuocTinh",'CHU',c.value FROM "CpsThongSoMoi" c JOIN "SanPham" s ON s."DuongDan"=c.slug JOIN "BienTheSanPham" b ON b."MaSanPham"=s."MaSanPham" AND b."MaHang"='CPS-'||upper(c.slug) JOIN "ThuocTinhDanhMuc" t ON t."MaPhanLoai"=s."MaPhanLoai" AND t."KyHieu"=c.code AND t."KieuDuLieu"='CHU' ON CONFLICT ("MaBienThe","MaThuocTinh") DO NOTHING;
